#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-08
// ============================================================================
// standards pass: /ork:review-pr --standards, offline with a stubbed agent()
// ============================================================================
// WHAT THIS GUARDS (two-pass review, card pocock-two-pass)
//
//   The builder never loads the repo's standards; a separate review pass reads
//   .github/review-standards.md and reports "S<n> (file:line) broken at
//   file:line". Each test names the change that makes it fail.
//
//   1. collect-rules.mjs --standards reads ONLY .github/review-standards.md.
//      Fails if --standards is ignored (CLAUDE.md, .claude/rules and
//      ~/.claude come back).
//   2. A repo without the file gives no sources and one `skip` line (operator
//      answer 2026-10-08: skip and log it). Fails if the skip line goes.
//   3. A symlinked standards file that leaves the repo is refused, not read.
//      Fails if the confine() check is dropped for --standards.
//   4. Standards mode numbers rules S1..Sn in file order and parses a leading
//      [glob] into a scope. Fails if the prefix stays R or [glob] stays in text.
//   5. A violation outside the rule's [glob] is out of scope; inside it, it
//      survives. Fails if the scope check in absorbVerifier is removed.
//   6. findingLines is "S<n> (<source>:<line>) broken at <file>:<line>".
//      Fails if the format loses the rule number or the rule's line.
//   7. Default mode is unchanged: R ids, [glob] text kept as written.
//      Fails if standards behaviour leaks into --rules.
//   9. The default standards strategy is the single-agent pass (operator,
//      2026-10-08): exactly 1 agent, holding every rule, told to refute its
//      own findings, at session effort, and 0 skeptics. Fails if the default
//      flips to the fan-out, or the self-refute line is dropped.
//  10. strategy "fanout" (the --rules opt-in) keeps one verifier per rule at
//      effort low plus one skeptic per violation. Fails if fanout is ignored.
//   8. The repo's own .github/review-standards.md has at most 20 rules and
//      3 KB, and every bullet is a rule. Fails if a 21st rule is added, or a
//      bullet has no directive word (it would be skipped silently).
//
// RULE_CHECK_SCRIPT / COLLECT_RULES_SCRIPT point the test at other copies,
// so it can be run against the pre-change files to show it fails there.
// ============================================================================

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const SKILL = path.join(REPO, 'src', 'skills', 'review-pr');
const SCRIPT = path.resolve(process.env.RULE_CHECK_SCRIPT || path.join(SKILL, 'workflows', 'rule-check.js'));
const COLLECT = path.resolve(process.env.COLLECT_RULES_SCRIPT || path.join(SKILL, 'scripts', 'collect-rules.mjs'));
const STANDARDS_FILE = path.join(REPO, '.github', 'review-standards.md');

const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
const SOURCE = readFileSync(SCRIPT, 'utf8');
const body = new AsyncFunction('args', 'agent', 'phase', 'log', 'pipeline', SOURCE.replace(/^export const meta/m, 'const meta'));

async function pipeline(items, ...stages) {
  return Promise.all(
    items.map(async (item, i) => {
      let v = item;
      try {
        for (let s = 0; s < stages.length; s++) v = await (s === 0 ? stages[s](item, item, i) : stages[s](v, item, i));
        return v;
      } catch {
        return null;
      }
    }),
  );
}

const calls = [];
async function run(args, answer) {
  calls.length = 0;
  const agent = async (prompt, opts) => {
    calls.push({ prompt, opts });
    return answer(opts, prompt);
  };
  return body(args, agent, () => {}, () => {}, pipeline);
}

let passed = 0;
const failures = [];
async function test(name, fn) {
  try {
    await fn();
    passed += 1;
    console.log(`PASS: ${name}`);
  } catch (e) {
    failures.push(name);
    console.log(`FAIL: ${name}\n  ${e.message.split('\n').join('\n  ')}`);
  }
}

const collect = (repo, home, extra = []) =>
  JSON.parse(execFileSync('node', [COLLECT, '--repo', repo, '--home', home, ...extra], { encoding: 'utf8' }));

const STANDARDS_MD = `# Review standards

<!-- read by the review pass only -->

- Never commit build output.
- [tests/**/*.sh] A shell lint must not read cmd | grep -q under pipefail.
- [.github/workflows/**] Always pin every third-party action by full commit SHA.
`;
const SRC = [{ path: '.github/review-standards.md', text: STANDARDS_MD }];
const idsIn = (prompt) => [...prompt.matchAll(/- ([RS]\d+) \(/g)].map((m) => m[1]);
// Every verifier reports one violation per rule it holds, at `file`:3.
const VIOLATE = (file) => (o, p) =>
  o.phase === 'Verify'
    ? { status: 'DONE', results: idsIn(p).map((ruleId) => ({ ruleId, applies: true, violations: [{ file, line: 3, quote: 'x', explanation: 'y' }] })) }
    : { refuted: false, reason: 'cannot refute' };

function fixture() {
  const root = mkdtempSync(path.join(tmpdir(), 'standards-pass-'));
  const repo = path.join(root, 'repo');
  const home = path.join(root, 'home');
  mkdirSync(path.join(repo, '.claude', 'rules'), { recursive: true });
  mkdirSync(path.join(repo, '.github'), { recursive: true });
  mkdirSync(path.join(home, '.claude', 'rules'), { recursive: true });
  writeFileSync(path.join(repo, 'CLAUDE.md'), '- Never do X.\n');
  writeFileSync(path.join(repo, '.claude', 'rules', 'a.md'), '- Always do Y.\n');
  writeFileSync(path.join(home, '.claude', 'CLAUDE.md'), '- Prefer W.\n');
  return { root, repo, home };
}

// 1
await test('--standards reads only .github/review-standards.md', async () => {
  const { root, repo, home } = fixture();
  try {
    writeFileSync(path.join(repo, '.github', 'review-standards.md'), STANDARDS_MD);
    const out = collect(repo, home, ['--standards']);
    assert.deepEqual(out.sources.map((s) => s.path), ['.github/review-standards.md']);
    assert.equal(out.skip, undefined);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

// 2
await test('a repo without the file: no sources and one skip line', async () => {
  const { root, repo, home } = fixture();
  try {
    const out = collect(repo, home, ['--standards']);
    assert.deepEqual(out.sources, []);
    assert.match(String(out.skip), /^standards pass skipped: .+ has no \.github\/review-standards\.md$/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

// 3
await test('a standards symlink that leaves the repo is refused, not read', async () => {
  const { root, repo, home } = fixture();
  try {
    const outside = path.join(root, 'secret.md');
    writeFileSync(outside, '- Never reveal SECRET_TOKEN_VALUE.\n');
    symlinkSync(outside, path.join(repo, '.github', 'review-standards.md'));
    const out = collect(repo, home, ['--standards']);
    assert.deepEqual(out.sources, []);
    assert.deepEqual(out.skipped, [{ file: '.github/review-standards.md', reason: 'symlink-escape' }]);
    assert.ok(!JSON.stringify(out).includes('SECRET_TOKEN_VALUE'));
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

// 4
await test('standards mode numbers rules S1..Sn and parses [glob] scopes', async () => {
  const r = await run({ mode: 'standards', target: 'PR #1', sources: SRC, changedFiles: ['a.txt'] }, VIOLATE('a.txt'));
  assert.deepEqual(r.rules.map((x) => [x.id, x.line, x.scope, x.text]), [
    ['S1', 5, null, 'Never commit build output.'],
    ['S2', 6, 'tests/**/*.sh', 'A shell lint must not read cmd | grep -q under pipefail.'],
    ['S3', 7, '.github/workflows/**', 'Always pin every third-party action by full commit SHA.'],
  ]);
});

// 5
await test('a violation outside the rule [glob] is out of scope, inside it survives', async () => {
  const r = await run({ mode: 'standards', target: 'PR #1', sources: SRC, changedFiles: ['tests/ci/x.sh'] }, VIOLATE('tests/ci/x.sh'));
  assert.deepEqual(r.survivors.map((v) => v.ruleId), ['S1', 'S2']);
  assert.deepEqual(r.outOfScope.map((v) => [v.ruleId, v.why]), [['S3', "file is outside the rule's scope .github/workflows/**"]]);
});

// 6
await test('findingLines name the rule number, its line, and the broken file:line', async () => {
  const r = await run({ mode: 'standards', target: 'PR #1', sources: SRC, changedFiles: ['tests/ci/x.sh'] }, VIOLATE('tests/ci/x.sh'));
  assert.deepEqual(r.findingLines, [
    'S1 (.github/review-standards.md:5) broken at tests/ci/x.sh:3',
    'S2 (.github/review-standards.md:6) broken at tests/ci/x.sh:3',
  ]);
});

// 7
await test('default mode keeps R ids and leaves [glob] text alone', async () => {
  const r = await run({ target: 'PR #1', sources: SRC, changedFiles: ['tests/ci/x.sh'] }, VIOLATE('tests/ci/x.sh'));
  assert.deepEqual(r.rules.map((x) => x.id), ['R1', 'R2', 'R3']);
  assert.equal(r.rules[1].text, '[tests/**/*.sh] A shell lint must not read cmd | grep -q under pipefail.');
  assert.equal(r.survivors.length, 3);
});

// 9
await test('default standards strategy: one agent with every rule, self-refute, no skeptics', async () => {
  const r = await run({ mode: 'standards', target: 'PR #1', sources: SRC, changedFiles: ['tests/ci/x.sh'] }, VIOLATE('tests/ci/x.sh'));
  assert.equal(r.strategy, 'single');
  assert.equal(calls.length, 1, `agent calls: ${calls.map((c) => c.opts.label).join(', ')}`);
  assert.equal(calls[0].opts.label, 'standards-pass');
  assert.equal(calls[0].opts.effort, undefined);
  assert.deepEqual(idsIn(calls[0].prompt), ['S1', 'S2', 'S3']);
  assert.match(calls[0].prompt, /try to refute it with one concrete check/);
  assert.equal(r.skepticsSpawned, 0);
  assert.deepEqual(r.survivors.map((v) => v.skeptic), ['self-refute (single-agent pass)', 'self-refute (single-agent pass)']);
});

// 10
await test('strategy fanout: one verifier per rule at effort low, one skeptic per violation', async () => {
  const r = await run({ mode: 'standards', strategy: 'fanout', target: 'PR #1', sources: SRC, changedFiles: ['tests/ci/x.sh'] }, VIOLATE('tests/ci/x.sh'));
  assert.equal(r.strategy, 'fanout');
  const verify = calls.filter((c) => c.opts.phase === 'Verify');
  assert.deepEqual(verify.map((c) => [c.opts.label, c.opts.effort]), [['verify:S1', 'low'], ['verify:S2', 'low'], ['verify:S3', 'low']]);
  assert.equal(r.skepticsSpawned, 2);
  assert.ok(!verify.some((c) => /try to refute it/.test(c.prompt)));
});

// 8
await test('the repo standards file: at most 20 rules and 3 KB, every bullet a rule', async () => {
  const text = readFileSync(STANDARDS_FILE, 'utf8');
  assert.ok(statSync(STANDARDS_FILE).size <= 3072, `${statSync(STANDARDS_FILE).size} bytes, cap 3072`);
  const bullets = text.split('\n').filter((l) => /^- /.test(l)).length;
  const r = await run({ mode: 'standards', target: 'repo', sources: [{ path: '.github/review-standards.md', text }], changedFiles: ['x'] }, VIOLATE('x'));
  assert.ok(r.rulesFound <= 20, `${r.rulesFound} rules, cap 20`);
  assert.equal(r.rulesFound, bullets, `skipped: ${JSON.stringify(r.skipped)}`);
  assert.deepEqual(r.skipped, []);
});

console.log(`\n${passed} passed, ${failures.length} failed`);
process.exit(failures.length ? 1 : 0);
